  switch (theme) {
    case BrandTheme.troubadour: return dark ? Color(0xFF100E08) : Color(0xFFF9EFDF);
    case BrandTheme.nuech: return Color(0xFF0E1220);
    case BrandTheme.garriga: return dark ? Color(0xFF14170E) : Color(0xFFEEF0E4);
    case BrandTheme.peira: return dark ? Color(0xFF16181B) : Color(0xFFE6E1D8);
    case BrandTheme.contraste: return Color(0xFF000000);
  }
}

